"use client";

import * as React from "react";
import { cn } from "@/lib/utils";

export type MorphSegmentItem = {
  value: string;
  label: string;
};

export type MorphSegmentProps = {
  items: MorphSegmentItem[];
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  className?: string;
};

/**
 * Morphing segmented control — the pill indicator springs between options.
 */
function MorphSegment({
  items,
  value,
  defaultValue,
  onValueChange,
  className,
}: MorphSegmentProps) {
  const [internal, setInternal] = React.useState(
    defaultValue ?? items[0]?.value ?? "",
  );
  const current = value ?? internal;
  const idx = Math.max(
    0,
    items.findIndex((i) => i.value === current),
  );
  const listRef = React.useRef<HTMLDivElement>(null);
  const [indicator, setIndicator] = React.useState({ left: 0, width: 0 });

  const measure = React.useCallback(() => {
    const root = listRef.current;
    if (!root) return;
    const btn = root.querySelectorAll("button")[idx] as HTMLButtonElement | undefined;
    if (!btn) return;
    setIndicator({ left: btn.offsetLeft, width: btn.offsetWidth });
  }, [idx]);

  React.useEffect(() => {
    measure();
    window.addEventListener("resize", measure);
    return () => window.removeEventListener("resize", measure);
  }, [measure, items]);

  const set = (v: string) => {
    if (value === undefined) setInternal(v);
    onValueChange?.(v);
  };

  return (
    <div
      ref={listRef}
      className={cn(
        "relative inline-flex rounded-full border border-border bg-muted/60 p-1",
        className,
      )}
      role="tablist"
    >
      <span
        aria-hidden
        className="absolute top-1 h-[calc(100%-0.5rem)] rounded-full bg-card shadow-[var(--shadow-soft)] transition-[left,width] duration-300 ease-[cubic-bezier(0.22,1,0.36,1)]"
        style={{ left: indicator.left, width: indicator.width }}
      />
      {items.map((item) => {
        const active = item.value === current;
        return (
          <button
            key={item.value}
            type="button"
            role="tab"
            aria-selected={active}
            onClick={() => set(item.value)}
            className={cn(
              "relative z-[1] rounded-full px-3.5 py-1.5 text-xs font-medium transition-colors",
              active ? "text-foreground" : "text-muted-foreground",
            )}
          >
            {item.label}
          </button>
        );
      })}
    </div>
  );
}

export { MorphSegment };
